ids=["LY-454","LY-455","LY-457","LY-458","LY-501","LY-502","LY-503","LY-504","LY-505","LY-506","LY-507","LY-508","LY-509","LY-510","LY-511","LY-512","LY-513","LY-514","LY-515","LY-516"]
for cid in ids:
    txt,basis,conf,tr=P[cid]
    obj={"case_id":cid,"prediction_text":txt,"basis":basis,"confidence":conf,"trigger":tr}
    with open(os.path.join(BASE,cid+".json"),"w",encoding="utf-8") as f:
        json.dump(obj,f,ensure_ascii=False,indent=1)
# 回读校验
cnt=0
for cid in ids:
    o=json.load(open(os.path.join(BASE,cid+".json"),encoding="utf-8"))
    assert o["case_id"]==cid
    for k in ["prediction_text","basis","confidence","trigger"]: assert k in o and o[k] not in (None,"")
    for k in ["changed_main","reserve_used","disputed","reason"]: assert k in o["trigger"]
    assert isinstance(o["trigger"]["changed_main"],bool) and isinstance(o["trigger"]["reserve_used"],bool) and isinstance(o["trigger"]["disputed"],bool)
    cnt+=1
assert cnt==len(ids)==20
cm=sum(P[c][3]["changed_main"] for c in ids); ru=sum(P[c][3]["reserve_used"] for c in ids); di=sum(P[c][3]["disputed"] for c in ids)
print(f"OK written={cnt} changed_main={cm} reserve_used={ru} disputed={di}")
